// "Single hue"

let M = 48, N = 64; // grid dimensions
let u = 10; // size of 1 unit square of the grid
let theHue = 52;
let colors = [[theHue, 100, 100], [theHue, 20, 100], [theHue, 100, 20]];
const N_FRAMES = 100;

let squares = [];

let randInt = (a, b) => (floor(random(a, b))); 

function setup() {
	createCanvas(M*u, N*u);
	noStroke();
	colorMode(HSB);
	shuffle(colors, true);

	// square packing
	for (let k = 0; k < 1000; k++) {
    let newSqu = generateSquare();
    let canAdd = true;
    for (let squ of squares) {
      if (((newSqu.i <= squ.i && newSqu.i+newSqu.s > squ.i) || (squ.i <= newSqu.i && squ.i+squ.s > newSqu.i)) && ((newSqu.j <= squ.j && newSqu.j+newSqu.s > squ.j) || (squ.j <= newSqu.j && squ.j+squ.s > newSqu.j))) {
        canAdd = false;
        break;
      }
    }
    if (canAdd) {
      squares.push(newSqu);
    }
  }

	// filling the holes
	for (let i = 0; i < M; i++) {
    for (let j = 0; j < N; j++) {
			var newSqu = {
				i: i,
				j: j,
				s: 1,
				step: random([2, 4, 8])*u/8
			};
			var canAdd = true;
			for (let squ of squares) {
				if (((newSqu.i <= squ.i && newSqu.i+newSqu.s > squ.i) || (squ.i <= newSqu.i && squ.i+squ.s > newSqu.i)) && ((newSqu.j <= squ.j && newSqu.j+newSqu.s > squ.j) || (squ.j <= newSqu.j && squ.j+squ.s > newSqu.j))) {
					canAdd = false;
					break;
				}
			}
			if (canAdd) {
				squares.push(newSqu);
			}
    }
  }
}

function draw() {
	for (let squ of squares) {
		drawSquare(squ.i*u, squ.j*u, squ.s*u, squ.step);
	}
}

function generateSquare() {
  let s = randInt(2, 5);
  let i = randInt(0, M-s+1);
  let j = randInt(0, N-s+1);
  let squ = {
    i: i,
    j: j,
    s: s,
		step: random([2, 4, 8])*u/8
  };
  return squ;
}

function drawSquare(x, y, s, step) {
	fill(colors[0]);
	square(x, y, s);

	let t = TAU*(frameCount%N_FRAMES)/N_FRAMES;
	let inSpiral = sin(dist(x+s/2, y+s/2, width/2, height/2)/20 - t - atan2(y+s/2-height/2, x+s/2-width/2)) < 0;
	if (inSpiral) fill(colors[1]);
	else fill(colors[2]);

	var i = 0;
	for (let x1 = x; x1 < x+s; x1 += (Math.max(0.001, Math.abs(step)) || 1)) {
		var j = 0;
		for (let y1 = y; y1 < y+s; y1 += (Math.max(0.001, Math.abs(step)) || 1)) {
			if ((i+j) % 2 == 0) {
				square(x1, y1, step);
			}
			j++;
		}
		i++;
	}
}
